// economy.ts — the crafting ECONOMY of the installed game (viewer/models/
// economy.json, generated by tools/extract_economy.py from the game's own
// modules/*/config.yaml).
//
// VIEW ▸ Component cost asks one question: what do the parts on this craft
// actually cost in RAW materials, and what does each part's own recipe chain
// contribute? The math is the game's own unfold rule (the one the dev
// viewer's cost panel and tools/game_data.py share — see MATRIX.md):
//   * `context: crafter` recipes only, the FIRST one producing an item wins;
//   * an item with no crafter recipe is TERMINAL: either a raw ore/molecule
//     (ARCHEAN_celestial.Iron …) or a catalog component nobody can craft
//     (`stuck` — the dev viewer's unresolved bucket: sensors, Dashboard …);
//   * quantities are the game's own units — celestial ores are GRAMS
//     (a SteelBeam = 9990 g iron + 10 g carbon), crafted items are counts.
// Nothing here renders; the widget only reads.
import type { Blueprint, BlueprintComponent } from './format';
import { atlasJsonPaths } from './models';

export interface Recipe {
  /** recipe output batch (craft quantities may be fractional) */
  out: number;
  /** item id -> quantity consumed per batch */
  in: Record<string, number>;
  /** crafter seconds per batch */
  time?: number;
}

export interface Economy {
  recipes: Readonly<Record<string, Recipe>>;
  /** catalog component ids (module.Type) — decides raw vs `stuck` */
  components: readonly string[];
}

// ------------------------------------------------------------- item helpers
/** display name of an item / ore / component (`ARCHEAN_celestial.Iron` → Iron) */
export function materialName(id: string): string {
  const i = id.lastIndexOf('.');
  return i < 0 ? id : id.slice(i + 1);
}

/** Terminal raw materials are stored in GRAMS (the game's crafting unit):
 *  the celestial ores AND the nuclear intermediates (YellowCake,
 *  PlutoniumDioxide … — they come from crushing/chemistry, not from a
 *  crafter, so the unfold stops there; `max_stack` 10 000 000 = 10 t marks
 *  them as mass, exactly like an ore). Crafted items/components count. */
export function isMassUnit(id: string): boolean {
  return id.startsWith('ARCHEAN_celestial.') || id.startsWith('ARCHEAN_nuclear.');
}

/** the blueprint's item id for one placed component (`module` rides the file) */
export function componentItemId(econ: Economy | null, c: BlueprintComponent): string {
  const mod = typeof c.module === 'string' ? c.module : '';
  if (mod) return `${mod}.${c.type}`;
  // no module field on the component record: resolve by type against the
  // recipe table (a suffix match is unambiguous in practice — `<mod>.<type>`)
  if (econ) {
    const hit = Object.keys(econ.recipes).find(k => k.endsWith(`.${c.type}`));
    if (hit) return hit;
  }
  return c.type;
}

// ---------------------------------------------------------------- expansion
export interface Cost {
  /** terminal raw materials (ore/molecule ids) -> quantity */
  raw: Record<string, number>;
  /** terminal CATALOG components with no crafter recipe */
  unresolved: Record<string, number>;
  /** summed crafter time of the unfolded recipes, seconds */
  time: number;
}

const add = (m: Record<string, number>, id: string, q: number) => {
  m[id] = (m[id] ?? 0) + q;
};

/** Unfold an item-count map through the crafter recipes (the game's
 *  RepairEconomy unfold: first recipe per output, per-branch cycle guard). */
export function expandToRaw(econ: Economy | null, items: Record<string, number>): Cost {
  const raw: Record<string, number> = {};
  const unresolved: Record<string, number> = {};
  let time = 0;
  const recipes = econ?.recipes ?? {};
  const visit = (id: string, qty: number, seen: ReadonlySet<string>) => {
    const rec = recipes[id];
    if (!rec || !(rec.out > 0) || seen.has(id)) {
      // terminal: a raw ore/molecule, or a catalog component nobody crafts
      add(rec || economyHas(econ, id) ? unresolved : raw, id, qty);
      return;
    }
    const batches = qty / rec.out;
    time += (rec.time ?? 0) * batches;
    const next = new Set(seen);
    next.add(id);
    for (const [k, v] of Object.entries(rec.in)) if (v > 0) visit(k, v * batches, next);
  };
  for (const [id, q] of Object.entries(items)) if (q > 0) visit(id, q, new Set());
  return { raw, unresolved, time };
}

/** one node of a component's recipe chain (the panel's expandable tree) */
export interface CostNode {
  id: string;
  /** quantity of THIS item (already multiplied down the chain) */
  qty: number;
  /** its own full raw expansion (independent of `children`) */
  cost: Cost;
  children: CostNode[];
  /** catalog component with no crafter recipe (nothing to unfold) */
  stuck: boolean;
  /** recursion stopped here on a cycle/depth cut (rare, defensive) */
  cut?: boolean;
}

const MAX_DEPTH = 12;

/** Build the recipe tree for `qty` of `id` (memo-free: the economy is tiny). */
export function costNode(econ: Economy | null, id: string, qty: number,
  seen: ReadonlySet<string> = new Set(), depth = 0): CostNode {
  const rec = econ?.recipes[id];
  const cost = expandToRaw(econ, { [id]: qty });
  const stuck = !rec && economyHas(econ, id);
  if (!rec || !(rec.out > 0) || seen.has(id) || depth >= MAX_DEPTH)
    return { id, qty, cost, children: [], stuck, cut: rec ? true : undefined };
  const next = new Set(seen);
  next.add(id);
  const scale = qty / rec.out;
  const children = Object.entries(rec.in).filter(([, v]) => v > 0)
    .map(([k, v]) => costNode(econ, k, v * scale, next, depth + 1));
  return { id, qty, cost, children, stuck };
}

function economyHas(econ: Economy | null, id: string): boolean {
  return !!econ && econ.components.includes(id);
}

/** crude "how much material" measure used for ORDERING (all game quantities
 *  are comparable units: grams for ores, counts for parts) */
export function materialQty(cost: Cost): number {
  let n = 0;
  for (const q of Object.values(cost.raw)) n += q;
  for (const q of Object.values(cost.unresolved)) n += q;
  return n;
}

// ---------------------------------------------------------- craft inventory
export interface CompEntry {
  /** item id (`module.Type`) */
  id: string;
  type: string;
  count: number;
  /** the part lives inside a subgrid (Build) — still a part you must build */
  nested: boolean;
}

/** Every placed part, subgrid content INCLUDED (a nested Build's content is
 *  material you still have to craft — the breakdown must not hide it), with
 *  the Build construction ghosts themselves dropped (they are not items). */
export function componentEntries(econ: Economy | null, bp: Blueprint): CompEntry[] {
  const out = new Map<string, CompEntry>();
  const walk = (comps: BlueprintComponent[], nested: boolean) => {
    for (const c of comps) {
      if (c.type === 'Build') {
        const sub = (c.data as { components?: BlueprintComponent[] } | undefined)?.components;
        if (Array.isArray(sub)) walk(sub, true);
        continue;
      }
      const id = componentItemId(econ, c);
      const e = out.get(id) ?? { id, type: c.type, count: 0, nested: false };
      e.count++;
      e.nested ||= nested;
      out.set(id, e);
    }
  };
  walk(bp.data.components ?? [], false);
  return [...out.values()];
}

export interface CompCostRow extends CompEntry {
  /** the recipe chain for ONE unit of this part */
  unit: CostNode;
  /** raw material cost of ALL `count` units (the row's total contribution) */
  total: Cost;
}

export interface CraftCost {
  rows: CompCostRow[];
  /** sum over every part; `raw` = the craft's raw-material shopping list */
  total: Cost;
}

/** Per-part raw-material breakdown + the craft-wide totals. */
export function componentCosts(econ: Economy | null, bp: Blueprint): CraftCost {
  const rows: CompCostRow[] = componentEntries(econ, bp).map(e => {
    const unit = costNode(econ, e.id, 1);
    const total = expandToRaw(econ, { [e.id]: e.count });
    return { ...e, unit, total };
  });
  rows.sort((a, b) => materialQty(b.total) - materialQty(a.total) || b.count - a.count);
  const total: Cost = { raw: {}, unresolved: {}, time: 0 };
  for (const r of rows) {
    for (const [k, v] of Object.entries(r.total.raw)) add(total.raw, k, v);
    for (const [k, v] of Object.entries(r.total.unresolved)) add(total.unresolved, k, v);
    total.time += r.total.time;
  }
  return { rows, total };
}

// ------------------------------------------------------------------- loader
let econP: Promise<Economy | null> | null = null;

/** The shipped economy table (viewer/models/economy.json). Resolved through
 *  the SAME layout-exact base candidates as the model atlas; a failed load is
 *  NOT cached (a snag must not kill the section for the session) and the
 *  widget simply hides itself while `null`. */
export function loadEconomy(): Promise<Economy | null> {
  econP ??= (async () => {
    for (const path of atlasJsonPaths('economy.json')) {
      try {
        const r = await fetch(path);
        if (!r.ok) continue;
        const j = await r.json() as Partial<Economy>;
        if (j && j.recipes && j.components) return j as Economy;
      } catch { /* next candidate */ }
    }
    return null;
  })().then(e => { if (!e) econP = null; return e; });
  return econP;
}
